import type { Vec3 } from '../contracts/math';

export type CameraMovementAction = 'camera-forward' | 'camera-backward' | 'camera-left' | 'camera-right';
export type CameraResetAction = 'camera-reset';

export interface CameraInputSource {
  isDown(action: CameraMovementAction): boolean;
  wasPressed(action: CameraResetAction): boolean;
  readonly pointer: { wheel: number };
}

export interface CameraInputCommand {
  /** Horizontal local movement; x is right, z is forward. */
  movement: Vec3;
  /** Signed number of camera-distance steps. Positive values zoom out. */
  zoom: number;
  resetRequested: boolean;
}

export interface CameraInputOptions {
  zoomStep?: number;
  maxWheelDelta?: number;
}

const EPSILON = 1e-6;
const DEFAULT_ZOOM_STEP = 0.01;
const DEFAULT_MAX_WHEEL_DELTA = 240;

/**
 * Converts abstract input actions into a frame command consumable by any camera
 * implementation. The class deliberately owns no DOM or Three.js references.
 */
export class CameraInput {
  private readonly zoomStep: number;
  private readonly maxWheelDelta: number;

  constructor(options: CameraInputOptions = {}) {
    this.zoomStep = Math.max(0, options.zoomStep ?? DEFAULT_ZOOM_STEP);
    this.maxWheelDelta = Math.max(0, options.maxWheelDelta ?? DEFAULT_MAX_WHEEL_DELTA);
  }

  read(input: CameraInputSource): CameraInputCommand {
    const rawX = Number(input.isDown('camera-right')) - Number(input.isDown('camera-left'));
    const rawZ = Number(input.isDown('camera-forward')) - Number(input.isDown('camera-backward'));
    const length = Math.hypot(rawX, rawZ);
    const movement = length > EPSILON
      ? { x: rawX / length, y: 0, z: rawZ / length }
      : { x: 0, y: 0, z: 0 };
    const wheel = Number.isFinite(input.pointer.wheel) ? input.pointer.wheel : 0;

    return {
      movement,
      zoom: Math.max(-this.maxWheelDelta, Math.min(this.maxWheelDelta, wheel)) * this.zoomStep,
      resetRequested: input.wasPressed('camera-reset'),
    };
  }
}
