import { describe, expect, it } from 'vitest';
import { CameraInput, type CameraInputSource } from './CameraInput';

function source(down: string[] = [], wheel = 0, reset = false): CameraInputSource {
  return {
    isDown: (action) => down.includes(action),
    wasPressed: () => reset,
    pointer: { wheel },
  };
}

describe('CameraInput', () => {
  it('maps WASD actions to normalized free-camera movement', () => {
    const command = new CameraInput().read(source(['camera-forward', 'camera-right']));
    expect(command.movement.x).toBeCloseTo(Math.SQRT1_2);
    expect(command.movement.y).toBe(0);
    expect(command.movement.z).toBeCloseTo(Math.SQRT1_2);
  });

  it('returns no movement for opposite or absent actions', () => {
    expect(new CameraInput().read(source(['camera-forward', 'camera-backward'])).movement).toEqual({ x: 0, y: 0, z: 0 });
  });

  it('converts and bounds wheel input into a zoom command', () => {
    const input = new CameraInput({ zoomStep: 0.1, maxWheelDelta: 20 });
    expect(input.read(source([], 12)).zoom).toBeCloseTo(1.2);
    expect(input.read(source([], -500)).zoom).toBeCloseTo(-2);
    expect(input.read(source([], Number.NaN)).zoom).toBe(0);
  });

  it('forwards reset only for the pressed frame', () => {
    expect(new CameraInput().read(source([], 0, true)).resetRequested).toBe(true);
    expect(new CameraInput().read(source()).resetRequested).toBe(false);
  });
});
